from __future__ import annotations

import os
import time
from typing import Any, Dict, Optional, Tuple

try:
    # Python 3.8+
    from importlib import metadata as importlib_metadata  # type: ignore
except Exception:  # pragma: no cover
    import importlib_metadata  # type: ignore


def _detect_root_package() -> str:
    """Best-effort detection of the root package name (e.g., 'core')."""
    name = __name__.split(".")[0]
    return name or "core"


def _resolve_version_from_module(pkg: str) -> Optional[str]:
    try:
        mod = __import__(pkg)
        v = getattr(mod, "__version__", None)
        if isinstance(v, str) and v:
            return v
    except Exception:
        pass
    return None


def _resolve_version_from_metadata(dist: str) -> Optional[str]:
    try:
        return importlib_metadata.version(dist)
    except Exception:
        return None


def _iso8601_from_env() -> Optional[str]:
    # Prefer explicit BUILD_DATE (ISO8601), else SOURCE_DATE_EPOCH (epoch seconds)
    bd = os.getenv("BUILD_DATE")
    if bd:
        return bd
    sde = os.getenv("SOURCE_DATE_EPOCH")
    if sde:
        try:
            ts = int(float(sde))
            return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(ts))
        except Exception:
            return None
    return None


def version_info(package_name: Optional[str] = None) -> Dict[str, Any]:
    """
    Return build/version metadata.

    Resolution order for version:
    1) Environment: APP_VERSION or BUILD_VERSION
    2) Module __version__ from detected root package (or provided package_name)
    3) importlib.metadata.version for the distribution name
    Fallback: "0.0.0-unknown"

    Additional fields:
    - commit: from GIT_COMMIT or GITHUB_SHA
    - build_date: from BUILD_DATE (ISO8601) or SOURCE_DATE_EPOCH
    - source: indicates resolution source used for version
    """
    src = ""
    version = os.getenv("APP_VERSION") or os.getenv("BUILD_VERSION")
    if version:
        src = "env"
    else:
        root = package_name or _detect_root_package()
        version = _resolve_version_from_module(root)
        if version:
            src = "module.__version__"
        else:
            # If a specific package_name provided, try that first; else try root
            target = package_name or root
            version = _resolve_version_from_metadata(target)
            if version:
                src = "importlib.metadata"

    if not version:
        version = "0.0.0-unknown"
        if not src:
            src = "fallback"

    commit = os.getenv("GIT_COMMIT") or os.getenv("GITHUB_SHA") or None
    build_date = _iso8601_from_env()

    return {
        "version": version,
        "commit": commit,
        "build_date": build_date,
        "source": src,
    }
